21	static int s_test_char_split_happy_path_fn(struct aws_allocator *allocator, void *ctx) {
22	    (void)ctx;
23	
24	    const char str_to_split[] = "testa;testb;testc";
25	
26	    struct aws_byte_buf to_split = aws_byte_buf_from_c_str(str_to_split);
27	
28	    struct aws_array_list output;
29	    ASSERT_SUCCESS(aws_array_list_init_dynamic(&output, allocator, 4, sizeof(struct aws_byte_cursor)));
30	    ASSERT_SUCCESS(aws_byte_buf_split_on_char(&to_split, ';', &output));
31	    ASSERT_INT_EQUALS(3, aws_array_list_length(&output));
32	
33	    struct aws_byte_cursor value = {0};
34	    ASSERT_SUCCESS(aws_array_list_get_at(&output, &value, 0));
35	
36	    char *expected = "testa";
37	
38	    ASSERT_BIN_ARRAYS_EQUALS(expected, strlen(expected), value.ptr, value.len);
39	
40	    ASSERT_SUCCESS(aws_array_list_get_at(&output, &value, 1));
41	    expected = "testb";
42	    ASSERT_BIN_ARRAYS_EQUALS(expected, strlen(expected), value.ptr, value.len);
43	
44	    ASSERT_SUCCESS(aws_array_list_get_at(&output, &value, 2));
45	    expected = "testc";
46	    ASSERT_BIN_ARRAYS_EQUALS(expected, strlen(expected), value.ptr, value.len);
47	
48	    aws_array_list_clean_up(&output);
49	
50	    return 0;
51	}
